def summary_ranges(nums):
    res, i = [], 0
    while i < len(nums):
        start = i
        while i + 1 < len(nums) and nums[i + 1] == nums[i] + 1:
            i += 1
        res.append(str(nums[start]) if start == i else f"{nums[start]}->{nums[i]}")
        i += 1
    return res

P08-merge-intervals#absorb:
def merge(intervals):
    merged = []                        # disjoint, in no particular order
    for start, end in intervals:
        rest = []
        for s, e in merged:
            if s <= end and start <= e:    # overlaps: absorb it
                start, end = min(start, s), max(end, e)
            else:
                rest.append([s, e])
        merged = rest + [[start, end]]
    return merged

P08-merge-intervals:
def merge(intervals):
    intervals.sort(key=lambda iv: iv[0])
    merged = []
    for start, end in intervals:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)   # extend the tail
        else:
            merged.append([start, end])
    return merged

P08-insert-interval#remerge:
def insert(intervals, new_interval):
    merged = []
    for start, end in sorted(intervals + [new_interval]):   # O(n log n) re-sort
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged
